@@ -87,17 +169,82 @@
         xmlFreeParserCtxt(pctxt);
 	return(NULL);
     }
-    inputPush(pctxt, inputStream);
+    if (inputPush(pctxt, inputStream) < 0) {
+        xmlFreeInputStream(inputStream);
+        xmlFreeParserCtxt(pctxt);
+        return(NULL);
+    }
     if (pctxt->directory == NULL)
         pctxt->directory = xmlParserGetDirectory((const char *) URI);

-    xmlParseDocument(pctxt);
+    /*
+     * Buffer and convert external documents before entering the parser.  A
+     * failed lazy encoding conversion can replace the parser input buffer
+     * while a name is being scanned, invalidating offsets held by libxml2.
+     * With no reader and no unconverted bytes left, parser growth cannot
+     * change the input buffer during such a scan.
+     */
+    inputBuffer = inputStream->buf;
+    if ((inputBuffer == NULL) || (inputBuffer->buffer == NULL))
+        goto parse_failed;
+    do {
+        ret = xmlParserInputBufferRead(inputBuffer, 4096);
+        content = xmlBufContent(inputBuffer->buffer);
+        if (content == NULL)
+            goto parse_failed;
+        inputStream->base = content;
+        inputStream->cur = content;
+        inputStream->end = xmlBufEnd(inputBuffer->buffer);
+    } while (ret > 0);
+    if ((ret < 0) || (inputBuffer->error != XML_ERR_OK))
+        goto parse_failed;
+
+    /* Prevent even an end-of-input callback from trying to grow buffers. */
+    inputBuffer->readcallback = NULL;
+    content = xmlBufContent(inputBuffer->buffer);
+    detected = xmlDetectCharEncoding(content,
+                    xmlBufUse(inputBuffer->buffer) > 4 ? 4 :
+                    (int) xmlBufUse(inputBuffer->buffer));
+    if ((detected != XML_CHAR_ENCODING_NONE) &&
+        (detected != XML_CHAR_ENCODING_UTF8)) {
+        if (xmlSwitchEncoding(pctxt, detected) < 0)
+            goto parse_failed;
+        if ((inputBuffer->error != XML_ERR_OK) ||
+            (pctxt->errNo == XML_ERR_NO_MEMORY) ||
+            ((inputBuffer->raw != NULL) &&
+             (xmlBufUse(inputBuffer->raw) != 0)))
+            goto parse_failed;
+    }
+
+    content = xmlBufContent(inputBuffer->buffer);
+    /*
+     * A signature-selected non-UTF-8 encoder has already converted the
+     * declaration as well as the document.  Don't feed that UTF-8 output
+     * through the declared encoder a second time.
+     */
+    if (((detected == XML_CHAR_ENCODING_NONE) ||
+         (detected == XML_CHAR_ENCODING_UTF8)) &&
+        xsltGetDeclaredEncoding(content, xmlBufUse(inputBuffer->buffer),
+                                encoding, sizeof(encoding))) {
+        if (xmlSwitchEncodingName(pctxt, encoding) < 0)
+            goto parse_failed;
+        if ((inputBuffer->error != XML_ERR_OK) ||
+            (pctxt->errNo == XML_ERR_NO_MEMORY) ||
+            ((inputBuffer->raw != NULL) &&
+             (xmlBufUse(inputBuffer->raw) != 0)))
+            goto parse_failed;
+    }
+
+    if (xmlParseDocument(pctxt) != 0)
+        goto parse_failed;

     if (pctxt->wellFormed) {
         doc = pctxt->myDoc;
+    } else {
+        goto parse_failed;
     }
-    else {
-        doc = NULL;
+parse_failed:
+    if (doc == NULL) {
         xmlFreeDoc(pctxt->myDoc);
         pctxt->myDoc = NULL;
     }

